                RecipientName = "Jane Smith",
                Description = "Furniture – 1 pallet"
            },
            new()
            {
                TrackingNumber = "SHP-20260712-10003",
                Origin = "Seattle, WA",
                Destination = "Denver, CO",
                Status = (int)ShipmentStatus.Delivered,
                ShippedDate = DateTime.UtcNow.AddDays(-7),
                EstimatedDelivery = DateTime.UtcNow.AddDays(-2),
                ActualDelivery = DateTime.UtcNow.AddDays(-2),
                CustomerEmail = "bob@example.com",
                RecipientName = "Bob Johnson",
                Description = "Auto parts – 5 boxes"
            },
            new()
            {
                TrackingNumber = "SHP-20260713-10004",
                Origin = "Houston, TX",
                Destination = "Phoenix, AZ",
                Status = (int)ShipmentStatus.OutForDelivery,
                ShippedDate = DateTime.UtcNow.AddDays(-2),
