+using System.Security.Claims;
+using Microsoft.AspNetCore.Identity;
+using Microsoft.EntityFrameworkCore;
+using ShipmentTracker.Client.Models;
+using ShipmentTracker.Data;
+using ShipmentTracker.Data.Entities;
+
+namespace ShipmentTracker.Endpoints;
+
+public static class ShipmentEndpoints
+{
+    public static void MapShipmentApi(this WebApplication app)
+    {
+        var group = app.MapGroup("api/shipments").RequireAuthorization();
+
+        // All shipments (dispatchers only)
+        group.MapGet("/", async (ApplicationDbContext db) =>
+        {
+            var shipments = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
+            return shipments.Select(ToDto);
+        }).RequireAuthorization("DispatcherPolicy");
+
+        // Track by tracking number (any authenticated user)
+        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
+        {
+            var shipment = await db.Shipments
+                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
+            return shipment is null ? Results.NotFound() : Results.Ok(ToDto(shipment));
+        });
+
+        // My shipments (current customer's shipments)
+        group.MapGet("/my", async (ClaimsPrincipal user, ApplicationDbContext db) =>
+        {
+            var email = user.FindFirstValue(ClaimTypes.Email) ?? "";
+            var shipments = await db.Shipments
+                .Where(s => s.CustomerEmail == email)
+                .OrderByDescending(s => s.ShippedDate)
+                .ToListAsync();
+            return shipments.Select(ToDto);
+        });
+
+        // Create shipment (dispatchers only)
+        group.MapPost("/", async (ShipmentDto dto, ApplicationDbContext db) =>
+        {
+            var entity = new Shipment
+            {
+                TrackingNumber = GenerateTrackingNumber(),
+                Origin = dto.Origin,
+                Destination = dto.Destination,
+                Status = (int)ShipmentStatus.Pending,
+                ShippedDate = DateTime.UtcNow,
+                EstimatedDelivery = dto.EstimatedDelivery,
+                CustomerEmail = dto.CustomerEmail,
+                RecipientName = dto.RecipientName,
+                Description = dto.Description
+            };
+            db.Shipments.Add(entity);
+            await db.SaveChangesAsync();
+            return Results.Created($"/api/shipments/track/{entity.TrackingNumber}", ToDto(entity));
+        }).RequireAuthorization("DispatcherPolicy");
