using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;
using ShipmentTracker.Data.Entities;

namespace ShipmentTracker;

/// <summary>
/// Server-side implementation that accesses the database directly,
/// used during interactive Server rendering before WASM takes over.
/// </summary>
public class ServerShipmentService(ApplicationDbContext db, AuthenticationStateProvider authStateProvider) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        var authState = await authStateProvider.GetAuthenticationStateAsync();
        var email = authState.User.FindFirstValue(ClaimTypes.Email) ?? "";
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var entity = new Shipment
        {
            TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Random.Shared.Next(10000, 99999)}",
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = (int)ShipmentStatus.Pending,
            ShippedDate = DateTime.UtcNow,
            EstimatedDelivery = dto.EstimatedDelivery,
            CustomerEmail = dto.CustomerEmail,
            RecipientName = dto.RecipientName,
            Description = dto.Description
        };
        db.Shipments.Add(entity);
        await db.SaveChangesAsync();
        return ToDto(entity);
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return;

        shipment.Status = (int)newStatus;
        if (newStatus == ShipmentStatus.Delivered)
            shipment.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentStatus)s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        ActualDelivery = s.ActualDelivery,
        CustomerEmail = s.CustomerEmail,
        RecipientName = s.RecipientName,
        Description = s.Description
    };
}

