    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private static string DaysRemaining(DateTime est)
    {
        var days = (est - DateTime.UtcNow).Days;
        return days switch
        {
            0 => "arriving today",
            1 => "1 day remaining",
            _ => $"{days} days remaining"
        };
