@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">
        You have no shipments. Use the tracking page to look up a shipment by tracking number.
    </div>
}
else
{
    <div class="row">
        @foreach (var s in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 @GetCardBorderClass(s.Status)">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@s.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Description:</strong> @s.Description</p>
                        <hr />
                        <p class="mb-1"><strong>Shipped:</strong> @s.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p class="mb-1">
                            <strong>Est. Delivery:</strong> @s.EstimatedDelivery.ToString("MMM dd, yyyy")
                            @if (s.EstimatedDelivery > DateTime.UtcNow && s.Status != ShipmentStatus.Delivered)
                            {
                                <span class="text-muted">(@DaysRemaining(s.EstimatedDelivery))</span>
                            }
                        </p>
                        @if (s.ActualDelivery.HasValue)
                        {
                            <p class="mb-0 text-success">
                                <strong>Delivered:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy")
                            </p>
                        }
                    </div>
                    <div class="card-footer">
                        <div class="progress" style="height: 8px;">
                            <div class="progress-bar @GetProgressBarClass(s.Status)"
                                 role="progressbar"
                                 style="width: @GetProgressPercent(s.Status)%">
                            </div>
                        </div>
                        <small class="text-muted">@GetProgressLabel(s.Status)</small>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private static string DaysRemaining(DateTime est)
    {
        var days = (est - DateTime.UtcNow).Days;
        return days switch
        {
            0 => "arriving today",
            1 => "1 day remaining",
            _ => $"{days} days remaining"
        };
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        ShipmentStatus.Returned => 100,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-primary"
    };

    private static string GetProgressLabel(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Awaiting pickup",
        ShipmentStatus.PickedUp => "Picked up from sender",
        ShipmentStatus.InTransit => "In transit to destination",
        ShipmentStatus.OutForDelivery => "Out for delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Delayed => "Shipment delayed",
        ShipmentStatus.Returned => "Returned to sender",
        _ => ""
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };

    private static string GetCardBorderClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "border-success",
        ShipmentStatus.Delayed => "border-danger",
        ShipmentStatus.Returned => "border-dark",
        _ => ""
    };
}

@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track a Shipment</h1>

<div class="row mb-4">
    <div class="col-md-8 col-lg-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260710-10001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchAsync" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header bg-dark text-white d-flex justify-content-between">
            <span>Tracking: <code class="text-light">@shipment.TrackingNumber</code></span>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row mb-3">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <p class="mb-1"><strong>From:</strong> @shipment.Origin</p>
                    <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                    <p class="mb-1"><strong>Recipient:</strong> @shipment.RecipientName</p>
                    <p class="mb-1"><strong>Contents:</strong> @shipment.Description</p>
                </div>
                <div class="col-md-6">
                    <h5>Delivery Information</h5>
                    <p class="mb-1"><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                    <p class="mb-1"><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <p class="mb-1 text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                    else if (shipment.Status != ShipmentStatus.Returned)
                    {
                        var days = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                        <p class="mb-1">
                            <strong>Time remaining:</strong>
                            @if (days > 0) { <span>@days day(s)</span> }
                            else if (days == 0) { <span class="text-warning">Arriving today</span> }
                            else { <span class="text-danger">Overdue by @Math.Abs(days) day(s)</span> }
                        </p>
                    }
                </div>
            </div>

            <h5>Shipment Progress</h5>
            <div class="progress mb-2" style="height: 24px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status) progress-bar-striped"
                     role="progressbar"
                     style="width: @GetProgressPercent(shipment.Status)%">
                    @shipment.Status
                </div>
            </div>

            <div class="d-flex justify-content-between text-muted small">
                <span>Pending</span>
                <span>Picked Up</span>
                <span>In Transit</span>
                <span>Out for Delivery</span>
                <span>Delivered</span>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? shipment;
    private bool isSearching;
    private bool searchPerformed;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchAsync();
    }

    private async Task SearchAsync()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        isSearching = true;
        searchPerformed = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        isSearching = false;
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Delayed => 55,
        ShipmentStatus.Returned => 100,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger progress-bar-animated",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

