@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

@if (showCreateForm)
{
    <div class="card mb-4">
        <div class="card-header">
            <h5 class="mb-0">Create New Shipment</h5>
        </div>
        <div class="card-body">
            <EditForm Model="newShipment" OnValidSubmit="CreateShipmentAsync" FormName="CreateShipment">
                <DataAnnotationsValidator />
                <div class="row g-3">
                    <div class="col-md-6">
                        <label class="form-label">Origin</label>
                        <InputText @bind-Value="newShipment.Origin" class="form-control" placeholder="City, State" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Destination</label>
                        <InputText @bind-Value="newShipment.Destination" class="form-control" placeholder="City, State" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Recipient Name</label>
                        <InputText @bind-Value="newShipment.RecipientName" class="form-control" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Customer Email</label>
                        <InputText @bind-Value="newShipment.CustomerEmail" class="form-control" type="email" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Estimated Delivery</label>
                        <InputDate @bind-Value="newShipment.EstimatedDelivery" class="form-control" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Description</label>
                        <InputText @bind-Value="newShipment.Description" class="form-control" />
                    </div>
                </div>
                <div class="mt-3">
                    <button type="submit" class="btn btn-success me-2" disabled="@isSaving">
                        @(isSaving ? "Saving..." : "Create Shipment")
                    </button>
                    <button type="button" class="btn btn-secondary" @onclick="() => showCreateForm = false">Cancel</button>
                </div>
            </EditForm>
        </div>
    </div>
}
else
{
    <button class="btn btn-primary mb-3" @onclick="() => showCreateForm = true">
        + New Shipment
    </button>
}

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking number, destination, or recipient..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            @if (s.Status != ShipmentStatus.Delivered && s.Status != ShipmentStatus.Returned)
                            {
                                <select class="form-select form-select-sm d-inline-block w-auto"
                                        @onchange="e => UpdateStatusAsync(s, e)">
                                    <option value="" disabled selected>Change status</option>
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        @if (status != s.Status)
                                        {
                                            <option value="@((int)status)">@status</option>
                                        }
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="text-muted">—</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-info alert-dismissible mt-3">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private ShipmentDto newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
    private bool showCreateForm;
    private bool isSaving;
    private string filterText = "";
    private string? statusMessage;

    private IEnumerable<ShipmentDto> FilteredShipments => shipments?
        .Where(s => string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.RecipientName.Contains(filterText, StringComparison.OrdinalIgnoreCase))
        ?? [];

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task CreateShipmentAsync()
    {
        isSaving = true;
        var created = await ShipmentService.CreateShipmentAsync(newShipment);
        shipments?.Insert(0, created);
        newShipment = new() { EstimatedDelivery = DateTime.UtcNow.AddDays(5) };
        showCreateForm = false;
        statusMessage = $"Shipment {created.TrackingNumber} created successfully.";
        isSaving = false;
    }

    private async Task UpdateStatusAsync(ShipmentDto shipment, ChangeEventArgs e)
    {
        if (e.Value is string val && int.TryParse(val, out var statusInt))
        {
            var newStatus = (ShipmentStatus)statusInt;
            await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
            if (newStatus == ShipmentStatus.Delivered)
                shipment.ActualDelivery = DateTime.UtcNow;
            statusMessage = $"Shipment {shipment.TrackingNumber} updated to {newStatus}.";
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Delayed => "bg-danger",
        ShipmentStatus.Returned => "bg-dark",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <div class="alert alert-info">
        You have no shipments. Use the tracking page to look up a shipment by tracking number.
    </div>
}
else
{
    <div class="row">
        @foreach (var s in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-4">
                <div class="card h-100 @GetCardBorderClass(s.Status)">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@s.TrackingNumber</code>
                        <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p class="mb-1"><strong>From:</strong> @s.Origin</p>
                        <p class="mb-1"><strong>To:</strong> @s.Destination</p>
                        <p class="mb-1"><strong>Description:</strong> @s.Description</p>
                        <hr />
                        <p class="mb-1"><strong>Shipped:</strong> @s.ShippedDate.ToString("MMM dd, yyyy")</p>
                        <p class="mb-1">
                            <strong>Est. Delivery:</strong> @s.EstimatedDelivery.ToString("MMM dd, yyyy")
                            @if (s.EstimatedDelivery > DateTime.UtcNow && s.Status != ShipmentStatus.Delivered)
                            {
                                <span class="text-muted">(@DaysRemaining(s.EstimatedDelivery))</span>
                            }
                        </p>
                        @if (s.ActualDelivery.HasValue)
                        {
                            <p class="mb-0 text-success">
                                <strong>Delivered:</strong> @s.ActualDelivery.Value.ToString("MMM dd, yyyy")
                            </p>
                        }
                    </div>
                    <div class="card-footer">
                        <div class="progress" style="height: 8px;">
                            <div class="progress-bar @GetProgressBarClass(s.Status)"
                                 role="progressbar"
                                 style="width: @GetProgressPercent(s.Status)%">
                            </div>
                        </div>
                        <small class="text-muted">@GetProgressLabel(s.Status)</small>
                    </div>
                </div>
            </div>
        }
    </div>
}

