@page "/track"
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track a Shipment</h1>

<div class="row mb-4">
    <div class="col-md-8 col-lg-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g. SHP-20260710-10001)"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchAsync" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searchPerformed && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>. Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header bg-dark text-white d-flex justify-content-between">
            <span>Tracking: <code class="text-light">@shipment.TrackingNumber</code></span>
            <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
        </div>
        <div class="card-body">
            <div class="row mb-3">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <p class="mb-1"><strong>From:</strong> @shipment.Origin</p>
                    <p class="mb-1"><strong>To:</strong> @shipment.Destination</p>
                    <p class="mb-1"><strong>Recipient:</strong> @shipment.RecipientName</p>
                    <p class="mb-1"><strong>Contents:</strong> @shipment.Description</p>
                </div>
                <div class="col-md-6">
                    <h5>Delivery Information</h5>
                    <p class="mb-1"><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMMM dd, yyyy")</p>
                    <p class="mb-1"><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</p>
                    @if (shipment.ActualDelivery.HasValue)
                    {
                        <p class="mb-1 text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMMM dd, yyyy")</p>
                    }
                    else if (shipment.Status != ShipmentStatus.Returned)
                    {
                        var days = (shipment.EstimatedDelivery - DateTime.UtcNow).Days;
                        <p class="mb-1">
                            <strong>Time remaining:</strong>
                            @if (days > 0) { <span>@days day(s)</span> }
                            else if (days == 0) { <span class="text-warning">Arriving today</span> }
                            else { <span class="text-danger">Overdue by @Math.Abs(days) day(s)</span> }
                        </p>
                    }
                </div>
            </div>

            <h5>Shipment Progress</h5>
            <div class="progress mb-2" style="height: 24px;">
                <div class="progress-bar @GetProgressBarClass(shipment.Status) progress-bar-striped"
                     role="progressbar"
                     style="width: @GetProgressPercent(shipment.Status)%">
                    @shipment.Status
                </div>
            </div>

            <div class="d-flex justify-content-between text-muted small">
                <span>Pending</span>
                <span>Picked Up</span>
                <span>In Transit</span>
                <span>Out for Delivery</span>
                <span>Delivered</span>
            </div>
        </div>
    </div>
}

